// THE SCORE: every time comes from the Mandarin dialogue (vo.js, generated by narration.py),
// so shots, lip-sync, captions, pop-up signs and sounds share one clock.
(function () {
  const node = typeof require !== 'undefined';
  const U = node ? require('./engine/util') : globalThis.U;
  const MU = node ? require('./engine/music') : globalThis.MUSIC;
  const VO = node ? require('./vo') : globalThis.VO;
  const { m, makeClock, makeChords } = MU;

  const FPS = 30;
  const FORMAT = U.pickFormat('16:9');
  const [W, H] = U.formatSize(FORMAT);
  const SAFE = U.safeArea(W, H);
  const WIDE = W / H > 1.2;
  const clock = makeClock({ bpm: 96, offset: 0 });
  const { T, BEAT } = clock;

  const L = {};
  for (const l of VO.lines) L[l.id] = l;
  const ph = (id, k) => L[id].phrases[k][1];
  const sent = (id, k) => L[id].sents[k][1];

  const ev = {
    hello: L.hello.t,
    jeep: L.jeep.t, unimog: ph('jeep', 1), // "它叫乌尼莫克"
    drive: L.drive.t - 0.5, thirty: ph('drive', 0), bumpy: sent('drive', 1),
    gear: L.gear.t - 0.6, helmet: ph('gear', 1) + 1.2, crampon: ph('gear', 1) + 2.4,
    carry: L.carry.t, wear: L.carry.t + 0.3, hold: sent('carry', 1), path: ph('carry', 2),
    ask: L.ask.t,
    walk: L.walk.t - 0.4, moraine: ph('walk', 1), rocks: ph('walk', 2),
    hard: L.hard.t, meter: L.hard.t + 0.4, slow: sent('hard', 1),
    cave: L.cave.t - 0.6, groups: L.cave.t + 0.6, follow: sent('cave', 1), stray: ph('cave', 2),
    photo: L.photo.t, lift: L.photo.t + 0.9,
    no: L.helmet.t, rule: ph('helmet', 1),
    ready: L.ready.t - 0.5, boots: L.ready.t + 0.4, clothes: L.ready.t + 1.6, go: sent('ready', 2),
  };
  const SPEECH_END = VO.lines[VO.lines.length - 1].end;
  ev.outro = SPEECH_END + 1.2;
  const DURATION = Math.ceil(SPEECH_END + 7.5);

  // shot cuts (the transitions are set in film.js)
  const cuts = { base: 0, drive: ev.drive, gear: ev.gear, walk: ev.walk, cave: ev.cave, ready: ev.ready, outro: ev.outro };

  // footsteps on the moraine walk: two crunches per walk cycle for each hiker
  const STEP = 0.4;
  const steps = [];
  for (let t = ev.walk + 0.6; t < ev.cave - 0.4; t += STEP / 2) steps.push({ t: +t.toFixed(3), pan: (Math.round(t * 10) % 3 - 1) * 0.3 });

  const { chords } = makeChords(clock, {
    Cmaj9: { notes: ['E3', 'G3', 'B3', 'D4'], bass: 'C2' },
    Am7: { notes: ['G3', 'C4', 'E4'], bass: 'A1' },
    Fmaj7: { notes: ['A3', 'C4', 'E4'], bass: 'F1' },
    G6: { notes: ['G3', 'B3', 'E4'], bass: 'G1' },
  }, Array.from({ length: Math.ceil(DURATION / 2.5 / 4) * 4 + 4 }, (_, i) => [i, 0, 4, ['Cmaj9', 'Am7', 'Fmaj7', 'G6'][Math.floor(i / 2) % 4]]));

  const markers = {
    hello: ev.hello, drive: ev.drive, gear: ev.gear, walk: ev.walk, cave: ev.cave, no: { t: ev.no, sync: 'a' },
    ready: ev.ready, outro: ev.outro,
  };

  const SCORE = { FPS, FORMAT, W, H, SAFE, WIDE, DURATION, clock, T, BEAT, m, chords, ev, cuts, markers, VO, L, STEP, steps };
  if (node) module.exports = SCORE; else globalThis.SCORE = SCORE;
})();
